{"file_path":"./src/graph.js","content":"/**
 * Cycle detection for the build graph, following the specification's exact
 * search order: depth-first from each task in ascending name order, walking
 * each task's dependencies in ascending name order.
 */

/**
 * Returns the first cycle the specified search order finds, as an array of
 * names running from the re-entered task through the search stack back to
 * a repeat of that task, or `null` when the graph is acyclic.
 */
export function findCycle(tasks, deps) {
  const names = [...tasks.keys()].sort()
  const state = new Map(names.map((name) => [name, 'unvisited']))
  const stack = []

  function visit(node) {
    state.set(node, 'visiting')
    stack.push(node)
    const dependencies = [...(deps.get(node) || [])].sort()
    for (const dependency of dependencies) {
      const dependencyState = state.get(dependency)
      if (dependencyState === 'visiting') {
        const start = stack.indexOf(dependency)
        return [...stack.slice(start), dependency]
      }
      if (dependencyState === 'unvisited') {
        const found = visit(dependency)
        if (found) return found
      }
    }
    stack.pop()
    state.set(node, 'done')
    return null
  }

  for (const name of names) {
    if (state.get(name) === 'unvisited') {
      const found = visit(name)
      if (found) return found
    }
  }
  return null
}
"}

