{"file_path":"./src/parse.js","content":"/**
 * Parsing of the build-graph text format described in the CLI's
 * specification: `task <name> <cost>` and `dep <name> <dependency>...`
 * directives, one per non-blank, non-comment line.
 */

const NAME_PATTERN = /^[A-Za-z0-9_.-]+$/
const COST_PATTERN = /^[0-9]+$/

export class ParseError extends Error {
  constructor(line, message) {
    super(message)
    this.line = line
  }
}

export class UnknownTaskError extends Error {
  constructor(name) {
    super(`unknown task ${name}`)
    this.name_ = name
  }
}

/**
 * Parses the graph text into a task-cost map and a dependency map (task
 * name to the set of names it directly depends on). Throws `ParseError`
 * for line-level syntax problems and `UnknownTaskError` for a `dep` line
 * that names a task no `task` line declares.
 */
export function parseInput(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const tasks = new Map()
  const depDirectives = []

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const words = trimmed.split(/\s+/)
    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) throw new ParseError(lineNo, 'expected task <name> <cost>')
      const [, name, costText] = words
      if (!NAME_PATTERN.test(name)) throw new ParseError(lineNo, `invalid task name ${name}`)
      if (!COST_PATTERN.test(costText)) throw new ParseError(lineNo, 'cost must be a non-negative integer')
      if (tasks.has(name)) throw new ParseError(lineNo, `task ${name} is declared twice`)
      tasks.set(name, parseInt(costText, 10))
    } else if (directive === 'dep') {
      if (words.length < 3) throw new ParseError(lineNo, 'expected dep <name> <dependency>...')
      const name = words[1]
      const dependencyNames = words.slice(2)
      for (const candidate of [name, ...dependencyNames]) {
        if (!NAME_PATTERN.test(candidate)) throw new ParseError(lineNo, `invalid task name ${candidate}`)
      }
      depDirectives.push({ name, dependencyNames })
    } else {
      throw new ParseError(lineNo, `unknown directive ${directive}`)
    }
  }

  for (const { name, dependencyNames } of depDirectives) {
    for (const candidate of [name, ...dependencyNames]) {
      if (!tasks.has(candidate)) throw new UnknownTaskError(candidate)
    }
  }

  const deps = new Map()
  for (const { name, dependencyNames } of depDirectives) {
    if (!deps.has(name)) deps.set(name, new Set())
    const set = deps.get(name)
    for (const dependency of dependencyNames) set.add(dependency)
  }

  return { tasks, deps }
}
"}

{"file_path":"./src/graph.js","content":"/**
 * Cycle detection for the build graph, following the specification's exact
 * search order: depth-first from each task in ascending name order, walking
 * each task's dependencies in ascending name order.
 */

/**
 * Returns the first cycle the specified search order finds, as an array of
 * names running from the re-entered task through the search stack back to
 * a repeat of that task, or `null` when the graph is acyclic.
 */
export function findCycle(tasks, deps) {
  const names = [...tasks.keys()].sort()
  const state = new Map(names.map((name) => [name, 'unvisited']))
  const stack = []

  function visit(node) {
    state.set(node, 'visiting')
    stack.push(node)
    const dependencies = [...(deps.get(node) || [])].sort()
    for (const dependency of dependencies) {
      const dependencyState = state.get(dependency)
      if (dependencyState === 'visiting') {
        const start = stack.indexOf(dependency)
        return [...stack.slice(start), dependency]
      }
      if (dependencyState === 'unvisited') {
        const found = visit(dependency)
        if (found) return found
      }
    }
    stack.pop()
    state.set(node, 'done')
    return null
  }

  for (const name of names) {
    if (state.get(name) === 'unvisited') {
      const found = visit(name)
      if (found) return found
    }
  }
  return null
}
"}

{"file_path":"./src/schedule.js","content":"/**
 * Timing computations for the build graph: unlimited-worker start/finish
 * times and wave depths, the downstream critical-path priority used by
 * `pack`, and the worker-packing simulation itself.
 */

/**
 * Computes, for every task, its start time, finish time and wave depth
 * under unlimited workers. A task's start is the greatest finish among its
 * dependencies (0 when it has none); its depth is one more than the
 * greatest depth among its dependencies (0 when it has none).
 */
export function computeTimes(tasks, deps) {
  const memo = new Map()

  function compute(name) {
    if (memo.has(name)) return memo.get(name)
    const dependencies = deps.get(name)
    let start = 0
    let depth = 0
    if (dependencies && dependencies.size > 0) {
      let maxFinish = 0
      let maxDepth = -1
      for (const dependency of dependencies) {
        const result = compute(dependency)
        if (result.finish > maxFinish) maxFinish = result.finish
        if (result.depth > maxDepth) maxDepth = result.depth
      }
      start = maxFinish
      depth = maxDepth + 1
    }
    const finish = start + tasks.get(name)
    const result = { start, finish, depth }
    memo.set(name, result)
    return result
  }

  for (const name of tasks.keys()) compute(name)
  return memo
}

/**
 * Computes each task's priority: the cost of the longest chain that begins
 * at it and runs through its dependents down to a task nothing depends on.
 */
function computePriority(tasks, deps) {
  const dependents = new Map()
  for (const name of tasks.keys()) dependents.set(name, [])
  for (const [name, dependencySet] of deps) {
    for (const dependency of dependencySet) {
      dependents.get(dependency).push(name)
    }
  }

  const memo = new Map()

  function compute(name) {
    if (memo.has(name)) return memo.get(name)
    let best = 0
    for (const successor of dependents.get(name)) {
      const value = compute(successor)
      if (value > best) best = value
    }
    const result = tasks.get(name) + best
    memo.set(name, result)
    return result
  }

  for (const name of tasks.keys()) compute(name)
  return memo
}

/**
 * Simulates the graph on the given number of workers, following the
 * specification's greedy rule: at each instant, while a worker is free and
 * a task is ready, start the ready task of greatest priority (ties broken
 * by ascending name) on the free worker of smallest index.
 */
export function pack(tasks, deps, workerCount) {
  const priority = computePriority(tasks, deps)
  const names = [...tasks.keys()]
  const workerFree = new Array(workerCount).fill(0)
  const workerLog = Array.from({ length: workerCount }, () => [])
  const finishTime = new Map()
  const started = new Set()

  function isReady(name, time) {
    const dependencies = deps.get(name)
    if (!dependencies) return true
    for (const dependency of dependencies) {
      const finish = finishTime.get(dependency)
      if (finish === undefined || finish > time) return false
    }
    return true
  }

  let time = 0
  while (started.size < names.length) {
    for (;;) {
      let freeWorker = -1
      for (let i = 0; i < workerCount; i++) {
        if (workerFree[i] <= time) {
          freeWorker = i
          break
        }
      }
      if (freeWorker === -1) break

      let best = null
      for (const name of names) {
        if (started.has(name) || !isReady(name, time)) continue
        if (best === null) {
          best = name
          continue
        }
        const bestPriority = priority.get(best)
        const namePriority = priority.get(name)
        if (namePriority > bestPriority || (namePriority === bestPriority && name < best)) best = name
      }
      if (best === null) break

      const finish = time + tasks.get(best)
      workerLog[freeWorker].push({ name: best, start: time, finish })
      workerFree[freeWorker] = finish
      finishTime.set(best, finish)
      started.add(best)
    }

    if (started.size >= names.length) break
    let next = Infinity
    for (let i = 0; i < workerCount; i++) {
      if (workerFree[i] > time) next = Math.min(next, workerFree[i])
    }
    if (next === Infinity) break
    time = next
  }

  let makespan = 0
  for (const finish of finishTime.values()) {
    if (finish > makespan) makespan = finish
  }
  return { workerLog, makespan }
}
"}

